SET	@prov_c := '%s';
SET	@id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);

SET	@b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

#DROP TABLE IF EXISTS s_opd10_sex;

CREATE TABLE IF NOT EXISTS s_opd10_sex(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	sex varchar(15) DEFAULT 0,
	groupcode298 int(5) DEFAULT 0,
	result int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year,sex,groupcode298),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
  ) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_opd10_sex WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_opd10_sex 
(
	SELECT
		@id,hospcode,areacode,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
		,sex,code298,SUM(result) as result
	FROM 
		t_diag_opd_sex ,chospital 
	WHERE code298 is not null 
		AND code298 NOT BETWEEN '268' AND '270' 
		AND code298 NOT in('243') 
		AND code298 NOT BETWEEN '290' AND '298'
		AND t_diag_opd_sex.hospcode=chospital.hoscode
		AND chospital.provcode = @prov_c
		AND sex in(1,2)
	GROUP BY 
		hospcode,areacode,sex,code298
	ORDER BY result DESC
);
